for (const [cmd, rel] of [['verify', 'scripts/pmu/verify-row.mjs'], ['prove', 'scripts/pmu/prove.mjs'], ['sense', 'scripts/pmu/sense.mjs'], ['attest', 'scripts/pmu/attest.mjs'], ['prove-rice', 'scripts/pmu/prove-rice.mjs'], ['hooper', 'scripts/pmu/hooper.mjs'], ['price-attest', 'scripts/pmu/price-attest.mjs'], ['attest-demo', 'scripts/pmu/attest-demo.mjs'], ['hypotheses', 'scripts/pmu/attest-hypotheses.mjs'], ['ur-attest', 'scripts/pmu/ur-attest.mjs'], ['perturb', 'scripts/pmu/attest-perturb.mjs'], ['attest-open', 'scripts/pmu/attest-open.mjs'], ['lens-tester', 'scripts/pmu/lens-tester-open.mjs'], ['lens-run', 'scripts/pmu/lens-run.mjs'], ['dinner-demo', 'scripts/pmu/dinner-demo.mjs'], ['publish-commit', 'scripts/pmu/publish-commit.mjs'], ['bootstrap', 'scripts/pmu/bootstrap.mjs'], ['proof', 'scripts/pmu/proof-monologue.mjs'], ['confidence', 'scripts/pmu/confidence-overlay.mjs'], ['annotate', 'scripts/pmu/annotate-regions.mjs'], ['portfolio', 'scripts/pmu/project-portfolio.mjs'], ['underwriter-grade', 'scripts/pmu/underwriter-grade.mjs'], ['settle', 'scripts/pmu/onchain-settle.mjs'], ['premium', 'scripts/pmu/calibration-premium.mjs'], ['ledger-attest', 'scripts/pmu/ledger-attest.mjs'], ['variance', 'scripts/pmu/variance-option.mjs'], ['anchor', 'scripts/pmu/onchain-anchor.mjs'], ['mesh-up', 'scripts/mesh/mesh-up.mjs'], ['spec-drift', 'scripts/pmu/spec-drift-check.mjs'], ['intervene', 'scripts/pmu/intervene.mjs'], ['e0', 'scripts/pmu/lens-e0.mjs'], ['miner', 'scripts/pmu/reef-miner.mjs'], ['harvest', 'scripts/pmu/harvest-agent.mjs'], ['sweep', 'scripts/pmu/lens-convergence-sweep.mjs'], ['loop-story', 'scripts/pmu/reef-loop-story.mjs'], ['register-surface', 'scripts/pmu/register-surface.mjs'], ['verify-baseline', 'scripts/pmu/verify-baseline.mjs'], ['init-fork', 'scripts/pmu/init-fork.mjs'], ['simulate-payout', 'scripts/pmu/simulate-payout.mjs'], ['my-pixel', 'scripts/pmu/my-pixel.mjs'], ['map-crawl', 'scripts/pmu/map-crawl.mjs'], ['verify-peer', 'scripts/pmu/verify-p