// tests/formal/verify-row.test.mjs — B13 THE VERIFIER (spec §8.50).
//
// Every row below is signed with a THROWAWAY ed25519 key generated fresh in this file via
// node:crypto — never the room's real (host-derived) identity. VR-1..VR-4 inject text/reef/walk
// so no real git repo or pmu-onchip binary is needed; VR-5 spawns the real CLI (one UNVERIFIABLE
// case needing neither, one MATCH and one MISMATCH case against the real fixture + repo); VR-6
// runs the real reconstruction (git + the real binary) against a real signed commit-reality row
// captured from HEAD (tests/formal/fixtures/b13-signed-commit-row.json).
//
// Each seen red under a one-token mutation (apply the listed change, run `node --test
// tests/formal/verify-row.test.mjs`, confirm the named test goes red, restore):
//   VR-1: change opts.walk's returned pixel from 'A,A' to 'B,B' → VR-1 fails (expects MATCH, gets MISMATCH)
//   VR-2: skip the byte-flip (use the row as signed, unmutated) → VR-2 fails (expects UNVERIFIABLE, gets MATCH)
//   VR-3: make opts.walk return the SAME pixel as the row → VR-3 fails (expects MISMATCH, gets MATCH)
//   VR-4: pass a `reef_blob` on the missing-reef case → VR-4's "missing reef" assertion fails (gets MATCH/MISMATCH, not UNVERIFIABLE)
//   VR-5: point --repo at a directory with no .thetacog/pmu binary for the MATCH case → VR-5 fails (exit 2, not 0)
//   VR-6: change one character of the fixture's `pixel` field → VR-6 fails (MISMATCH, not MATCH) — this is the row-tamper case,
//         distinct from VR-2 because a tampered `pixel` is also a tampered SIGNED FIELD, so in practice it reads UNVERIFIABLE
//         (proving the signature — not the walk — is what actually gates a tamper); confirmed by hand during this build.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { generateKeyPairSync, sign as edSign, createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { mkdtempSync, writeFileSync, chmodSync, existsSync, readFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { verifyRow, canonicalTuple, SIG_FIELDS, EXIT_CODE } from '../../scripts/pmu/verify-row.mjs';

const REPO = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..');
const SERVER = resolve(REPO, 'packages/thetacog-mcp/server.js');
const FIXTURE = resolve(REPO, 'tests/formal/fixtures/b13-signed-commit-row.json');
const sha12 = (s) => createHash('sha256').update(Buffer.from(s)).digest('hex').slice(0, 12);

// ── a throwaway ed25519 identity, generated fresh in this file (never the room key) ──────────
const { privateKey, publicKey } = generateKeyPairSync('ed25519');
const pubkeyHex = Buffer.from(publicKey.export({ format: 'jwk' }).x, 'base64url').toString('hex');
function signRow(row) {
  const sig = edSign(null, Buffer.from(canonicalTuple(row)), privateKey).toString('hex');
  return { ...row, sig, sig_pubkey: pubkeyHex };
}

// A minimal, valid, unsigned 'turn' row over some text — every SIG_FIELDS entry present.
function baseTurnRow(text, pixel = 'A,A') {
  return {
    ts: '2026-01-01T00:00:00.000Z', source: 'turn', text_sha: sha12(text), pixel,
    reef_sha: 'aaaaaaaaaaaaaaaa', axes_sha: 'bbbbbbbbbbbbbbbb', bin_sha: 'cccccccccccccccc',
    reef_blob: 'reef-test-blob', axes_blob: 'axes-test-blob', room: 'formal-test',
  };
}

test('VR-1 — a row signed over the canonical tuple verifies and reads MATCH when the injected walk reproduces the pixel', () => {
  const text = 'find the running code first, then measure the rate against its null';
  const row = signRow(baseTurnRow(text, 'A,A'));
  const out = verifyRow(row, {
    readText: () => text,
    readReef: () => Buffer.from('reef-bytes'),
    walk: (usedText, reefBytes) => { assert.equal(usedText, text); assert.equal(reefBytes.toString(), 'reef-bytes'); return 'A,A'; },
  });
  assert.equal(out.verdict, 'MATCH');
  assert.equal(out.signature.valid, true);
  assert.match(out.reason, /^placement: row A,A recomputed A,A$/);
});

test('VR-2 — one byte changed in any signed field → UNVERIFIABLE (signature invalid), never MATCH or MISMATCH', () => {
  const text = 'a signed tuple with one byte flipped must never verify';
  const signed = signRow(baseTurnRow(text, 'A,A'));
  for (const field of SIG_FIELDS) {
    const tampered = { ...signed, [field]: field === 'pixel' ? 'B,B' : `${signed[field]}x` };
    const out = verifyRow(tampered, { readText: () => text, readReef: () => Buffer.from('x'), walk: () => 'A,A' });
    assert.equal(out.verdict, 'UNVERIFIABLE', `tampering '${field}' must read UNVERIFIABLE`);
    assert.match(out.reason, /^signature: invalid over/, `tampering '${field}' must give the invalid-signature reason`);
    assert.equal(out.signature.valid, false);
  }
  // and the untampered row still verifies, proving the loop above tampered something real each time
  const clean = verifyRow(signed, { readText: () => text, readReef: () => Buffer.from('x'), walk: () => 'A,A' });
  assert.equal(clean.verdict, 'MATCH');
});

test('VR-3 — a validly signed row whose pixel the walk does not reproduce → MISMATCH with both pixels in the reason', () => {
  const text = 'a real signature over a placement the reef no longer agrees with';
  const row = signRow(baseTurnRow(text, 'A,A'));
  const out = verifyRow(row, { readText: () => text, readReef: () => Buffer.from('reef-bytes'), walk: () => 'B,B' });
  assert.equal(out.verdict, 'MISMATCH');
  assert.equal(out.signature.valid, true, 'MISMATCH requires the signature to be VALID — an invalid one is UNVERIFIABLE, not MISMATCH');
  assert.match(out.reason, /row A,A recomputed B,B/);
  assert.equal(out.placement.row, 'A,A');
  assert.equal(out.placement.recomputed, 'B,B');
});

test('VR-4 — missing public key, missing reef, or a prompt row without --text → UNVERIFIABLE with the specific reason', () => {
  const text = 'three ways a row can be honestly unreachable';

  // (a) missing public key
  const noPub = signRow(baseTurnRow(text, 'A,A'));
  delete noPub.sig_pubkey;
  const outA = verifyRow(noPub, { readText: () => text, readReef: () => Buffer.from('x'), walk: () => 'A,A' });
  assert.equal(outA.verdict, 'UNVERIFIABLE');
  assert.match(outA.reason, /^signature: missing sig_pubkey$/);

  // (b) missing reef — signature and text both check out, but no reef_blob and nothing injected to supply it
  const noReefRow = signRow({ ...baseTurnRow(text, 'A,A'), reef_blob: null });
  const outB = verifyRow(noReefRow, { readText: () => text, repo: REPO });
  assert.equal(outB.verdict, 'UNVERIFIABLE');
  assert.match(outB.reason, /^reef: blob null not available/);

  // (c) a prompt row with no --text supplied at all (no readText, no commit ref)
  const promptRow = signRow(baseTurnRow(text, 'A,A'));
  const outC = verifyRow(promptRow, { repo: REPO });
  assert.equal(outC.verdict, 'UNVERIFIABLE');
  assert.match(outC.reason, /^text: prompt rows carry text_sha only; supply --text <file>$/);
});

test('VR-5 — the CLI: exit codes 0/1/2 and the first stdout line is exactly the token', () => {
  // (a) UNVERIFIABLE — no repo/binary needed: an unsigned row
  const dir = mkdtempSync(join(tmpdir(), 'verify-row-cli-'));
  const badRow = baseTurnRow('unsigned', 'A,A'); // no sig at all
  const badPath = join(dir, 'bad.json'); writeFileSync(badPath, JSON.stringify(badRow));
  const r1 = spawnCli(['verify', badPath]);
  assert.equal(r1.status, EXIT_CODE.UNVERIFIABLE);
  assert.equal(r1.firstLine, 'UNVERIFIABLE');
  assert.match(r1.stdout, /^reason: /m);

  if (!existsSync(FIXTURE)) { console.log('VR-5 (b)/(c) skipped: no fixture at', FIXTURE); return; }
  const fixtureRow = JSON.parse(readFileSync(FIXTURE, 'utf8'));

  // (b) MATCH — the real fixture, the real repo, the real binary (never rebuilt, only run)
  const binPath = resolve(REPO, '.thetacog/pmu/target/release/pmu-onchip');
  if (!existsSync(binPath)) { console.log('VR-5 (b) skipped: pmu-onchip binary not built'); }
  else {
    const r2 = spawnCli(['verify', FIXTURE, '--repo', REPO]);
    assert.equal(r2.status, EXIT_CODE.MATCH, r2.stdout + r2.stderr);
    assert.equal(r2.firstLine, 'MATCH');
  }

  // (c) MISMATCH — same real signed row, but PMU_BINARY points at a fake walker that always
  // answers a different pixel. The signature is untouched and still valid; only the recomputed
  // placement differs, which is exactly what MISMATCH (as opposed to UNVERIFIABLE) means.
  const fakeBin = join(dir, 'fake-pmu-onchip.mjs');
  writeFileSync(fakeBin, `#!/usr/bin/env node\nconsole.log(JSON.stringify({ pixel: ${JSON.stringify(fixtureRow.pixel === 'Z,Z' ? 'Y,Y' : 'Z,Z')} }));\n`);
  chmodSync(fakeBin, 0o755);
  const r3 = spawnCli(['verify', FIXTURE, '--repo', REPO], { PMU_BINARY: fakeBin });
  assert.equal(r3.status, EXIT_CODE.MISMATCH, r3.stdout + r3.stderr);
  assert.equal(r3.firstLine, 'MISMATCH');
});

test('VR-6 — end to end on one real signed commit row from the tape, in this repository → MATCH', () => {
  if (!existsSync(FIXTURE)) { console.log('VR-6 skipped: no fixture at', FIXTURE); return; }
  const row = JSON.parse(readFileSync(FIXTURE, 'utf8'));
  const binPath = resolve(REPO, '.thetacog/pmu/target/release/pmu-onchip');
  if (!existsSync(binPath)) { console.log('VR-6 skipped: pmu-onchip binary not built at', binPath); return; }
  const out = verifyRow(row, { repo: REPO });
  assert.equal(out.verdict, 'MATCH', `expected MATCH, got ${out.verdict}: ${out.reason}`);
  assert.equal(out.signature.valid, true);
  assert.equal(out.placement.recomputed, row.pixel);
});

// execFileSync throws on a non-zero exit (1 and 2 both are), so the real exit code and both
// streams are read off the thrown error — never off a resolved return, which only the 0 case gives.
function spawnCli(args, env = {}) {
  try {
    const stdout = execFileSync(process.execPath, [SERVER, ...args], {
      encoding: 'utf8', env: { ...process.env, ...env }, cwd: REPO, timeout: 130000, maxBuffer: 8 * 1024 * 1024,
    });
    return { status: 0, stdout, stderr: '', firstLine: stdout.split('\n')[0] };
  } catch (e) {
    const stdout = String(e.stdout || '');
    return { status: e.status, stdout, stderr: String(e.stderr || ''), firstLine: stdout.split('\n')[0] };
  }
}
